#include <vector>
#define main hecbench_original_main
#include "wedford-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):10,bs=16,ss=64,fs=8,n=bs*ss*fs;std::vector<float>input(n),mean(fs),var(fs);for(int i=0;i<n;i++)input[i]=float((i*17)%1024)/1024.f;std::vector<double>expectedmean(fs),expectedvar(fs);for(int f=0;f<fs;f++){double sum=0;for(int b=0;b<bs;b++)for(int s=0;s<ss;s++)sum+=double(input[b*ss*fs+f*ss+s]);double m=sum/(bs*ss);expectedmean[f]=m;double variance=0;for(int b=0;b<bs;b++)for(int s=0;s<ss;s++){double d=double(input[b*ss*fs+f*ss+s])-m;variance+=d*d;}expectedvar[f]=variance/(bs*ss);}std::vector<double>expected=expectedmean;expected.insert(expected.end(),expectedvar.begin(),expectedvar.end());float *di,*dm,*dv;cudaMalloc(&di,n*4);cudaMalloc(&dm,fs*4);cudaMalloc(&dv,fs*4);cudaMemcpy(di,input.data(),n*4,cudaMemcpyHostToDevice);dim3 threads(32,16);welford_kernel<float,float,float><<<fs,threads>>>(di,dm,dv,bs,fs,ss);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)welford_kernel<float,float,float><<<fs,threads>>>(di,dm,dv,bs,fs,ss);cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;cudaMemcpy(mean.data(),dm,fs*4,cudaMemcpyDeviceToHost);cudaMemcpy(var.data(),dv,fs*4,cudaMemcpyDeviceToHost);std::vector<double>values(mean.begin(),mean.end());values.insert(values.end(),var.begin(),var.end());emit(trial,seconds,values,expected,repeat,1e-3);}cudaFree(di);cudaFree(dm);cudaFree(dv);return 0;}
